#!/usr/bin/env node
/**
 * The hand-written browse app and the generated browse data must still agree.
 *
 * THE ACTUAL RISK, WHICH IS NOT "IT IS HAND-WRITTEN"
 *
 * Tech-debt item 11 says `browse/` is hand-written rather than built. On its own that is
 * not a defect -- plenty of good code is hand-written. The defect is the ASYMMETRY: the
 * data under `data/browse/` is regenerated by build-browse-indexes.mjs on every build,
 * while `browse/browse.js` reads it by hand, and nothing connects the two. The reader can
 * be silently wrong about a file the generator has since changed.
 *
 * That is not hypothetical. On 2026-08-23 exactly this bug was found in the OTHER reader:
 * data/browse/persons.json had been sharded into a manifest with no `items` array, and
 * app/src/app.js still read `payload.items`. It resolved to [], every person link in the
 * election panes silently did nothing, and no test, validator or error surfaced it.
 * browse.js happened to handle the sharded layout; nothing guaranteed that it would.
 *
 * So this checks the CONTRACT rather than the authorship:
 *
 *   1. every index named in browse.js's ENTITY_CONFIG exists
 *   2. each one is readable and carries entries -- either `items`, or the sharded
 *      manifest shape (`indexLayout: "sharded"` with a `shards` array) that browse.js
 *      knows how to expand
 *   3. every shard a manifest names is actually present
 *   4. every configured detailDir exists, OR every item carries a detailUrl instead --
 *      loadDetail() prefers detailUrl and only falls back to the directory, so a mix of
 *      the two is the dangerous case and is the one that fails here
 *
 * ENTITY_CONFIG is parsed out of browse.js itself, so adding an entity to the app without
 * generating its index fails here.
 *
 * Offline, so it belongs to `check:` rather than `verify:`.
 *
 *   node scripts/validate-browse-contract.mjs
 */
import { readFileSync, existsSync } from 'node:fs';

const BROWSE_JS = 'browse/browse.js';
const DATA_ROOT = 'data/browse';

const source = readFileSync(BROWSE_JS, 'utf8');
const start = source.indexOf('const ENTITY_CONFIG = {');
if (start === -1) {
  console.error(`FAIL: ENTITY_CONFIG not found in ${BROWSE_JS}. If it was renamed, update this validator --`);
  console.error('  a validator that cannot find what it checks must fail, not pass.');
  process.exit(1);
}
const end = source.indexOf('\n};', start);
const block = source.slice(start, end);

const entities = [];
for (const line of block.split('\n')) {
  const index = /index:\s*'([^']+)'/.exec(line);
  if (!index) continue;
  const key = /^\s*'?([\w-]+)'?\s*:/.exec(line);
  const detailDir = /detailDir:\s*'([^']+)'/.exec(line);
  const listIndex = /listIndex:\s*'([^']+)'/.exec(line);
  entities.push({ key: key ? key[1] : '(unknown)', index: index[1], listIndex: listIndex ? listIndex[1] : null, detailDir: detailDir ? detailDir[1] : null });
}

if (!entities.length) {
  console.error(`FAIL: parsed ENTITY_CONFIG from ${BROWSE_JS} but found no index entries.`);
  process.exit(1);
}

// PRONI is served from D1 through /_api/proni/*, not from static files. browse.js says so
// at browse/browse.js:848 and its route renders directly from the API rather than the
// generic index lookup, so `index: 'proni.json'` in ENTITY_CONFIG is vestigial -- the file
// has never existed and should not. Skipped here rather than "fixed" by generating a file
// nothing reads.
const API_SERVED = new Set(['proni']);

const problems = [];
const notes = [];
let totalItems = 0;

for (const entity of entities) {
  if (API_SERVED.has(entity.key)) {
    notes.push(`${entity.key}: served from D1 via /_api/${entity.key}/*, no static index expected`);
    continue;
  }
  const path = `${DATA_ROOT}/${entity.index}`;
  if (!existsSync(path)) {
    problems.push(`${entity.key}: index ${path} does not exist`);
    continue;
  }
  let payload;
  try {
    payload = JSON.parse(readFileSync(path, 'utf8'));
  } catch (error) {
    problems.push(`${entity.key}: ${path} is not valid JSON (${error.message})`);
    continue;
  }

  if (payload.indexLayout === 'sharded') {
    if (!Array.isArray(payload.shards) || !payload.shards.length) {
      problems.push(`${entity.key}: ${path} says indexLayout "sharded" but names no shards`);
      continue;
    }
    let count = 0;
    for (const shard of payload.shards) {
      // browse.js resolves shard.url as a site-absolute path; on disk it is repo-relative.
      const shardPath = String(shard.url || '').replace(/^\//, '');
      if (!shardPath || !existsSync(shardPath)) {
        problems.push(`${entity.key}: shard ${shard.url || shard.name} is named but missing on disk`);
        continue;
      }
      count += Number(shard.count) || 0;
    }
    totalItems += count;
  } else if (Array.isArray(payload.items)) {
    totalItems += payload.items.length;
  } else {
    problems.push(`${entity.key}: ${path} has neither an "items" array nor a sharded manifest — browse.js will render nothing`);
  }

  // detailDir is a FALLBACK, not the only path. loadDetail() prefers item.detailUrl when
  // an item carries one -- that is how sources and register-interests reach their shards
  // -- and only falls back to details/<detailDir>/<slug>.json otherwise. So the directory
  // is required only for entities whose items have no detailUrl.
  //
  // This distinction is worth keeping rather than simplifying away: it is a real latent
  // trap. An item that arrives WITHOUT a detailUrl in a shard-based entity falls back to
  // a directory that does not exist and 404s, and browse.js rethrows that for every type
  // except elections. Reported as a note so the shape is visible without failing a build
  // over a directory nothing currently needs.
  // A list index (elections-list.json) is what the list view reads; browse.js falls back to the
  // full index without one, but a configured one that is missing or empty is a build gap.
  if (entity.listIndex) {
    const listPath = `${DATA_ROOT}/${entity.listIndex}`;
    let listPayload = null;
    try { listPayload = JSON.parse(readFileSync(listPath, 'utf8')); } catch { listPayload = null; }
    if (!listPayload || !Array.isArray(listPayload.items) || !listPayload.items.length) {
      problems.push(`${entity.key}: list index ${listPath} is missing or has no items`);
    } else if (Array.isArray(payload.items) && listPayload.items.length !== payload.items.length) {
      problems.push(`${entity.key}: ${listPath} lists ${listPayload.items.length} records, ${path} has ${payload.items.length}`);
    }
  }

  if (!entity.detailDir) continue;
  const dir = `${DATA_ROOT}/details/${entity.detailDir}`;
  if (existsSync(dir)) continue;
  const items = Array.isArray(payload.items) ? payload.items : [];
  const withDetailUrl = items.filter((item) => item && item.detailUrl).length;
  if (items.length && withDetailUrl === items.length) {
    notes.push(`${entity.key}: no ${dir}, but all ${items.length} item(s) carry detailUrl (shard-served)`);
  } else if (items.length && withDetailUrl) {
    problems.push(`${entity.key}: ${items.length - withDetailUrl} of ${items.length} item(s) lack detailUrl and ${dir} does not exist — those will 404`);
  } else if (items.length) {
    problems.push(`${entity.key}: detailDir ${dir} does not exist and no item carries detailUrl`);
  } else {
    notes.push(`${entity.key}: no ${dir}; index is sharded, detail paths not verifiable offline`);
  }
}

if (problems.length) {
  console.error(`FAIL: ${problems.length} browse contract problem(s).`);
  for (const problem of problems) console.error(`  - ${problem}`);
  console.error('');
  console.error('  browse/browse.js reads these by hand. A missing or reshaped index does not');
  console.error('  raise an error there — it renders an empty list, which looks like no data.');
  process.exit(1);
}

for (const note of notes) console.log(`  note: ${note}`);
console.log(`PASS: ${entities.length} browse entit(ies) resolve, ${totalItems.toLocaleString()} indexed records.`);
